import{_ as a,a as i,c as t,ac as n}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"思考与方法：把问题写成可检验判断","description":"以读书小组练习任务边界、事实与推断、备选解释和单次干预的证据范围。","frontmatter":{"title":"思考与方法：把问题写成可检验判断","description":"以读书小组练习任务边界、事实与推断、备选解释和单次干预的证据范围。","showdocs":{"topics":[{"id":"thinking","title":"思考与方法","link":"/topics/thinking/"}],"kind":"问题与证据方法","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"思考与方法：把问题写成可检验判断","summary":"以读书小组练习任务边界、事实与推断、备选解释和单次干预的证据范围。","status":"active","related":[{"title":"思考与方法：分析框架、定义与证据边界","link":"/life/thinking/analysis/frameworks","kind":"框架及面试复习材料","scope":"general","audience":"general"},{"title":"思考与方法：复盘记录与行动收敛","link":"/life/thinking/retrospective/retrospective","kind":"偏差与后续行动","scope":"general","audience":"general"},{"title":"思考与方法：一次虚构讨论改进案例","link":"/life/thinking/reference/case-study","kind":"案例推演与复盘","scope":"general","audience":"general"}],"prev":false,"next":{"text":"思考与方法：一次虚构讨论改进案例","link":"/life/thinking/reference/case-study"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"思考与方法：一次虚构讨论改进案例","link":"/life/thinking/reference/case-study"}},"headers":[],"relativePath":"life/thinking/analysis/methods.md","filePath":"life/thinking/analysis/methods.md"}'),s={name:"life/thinking/analysis/methods.md"};function r(l,e,o,d,c,h){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="思考与方法-把问题写成可检验判断" tabindex="-1">思考与方法：把问题写成可检验判断 <a class="header-anchor" href="#思考与方法-把问题写成可检验判断" aria-label="Permalink to &quot;思考与方法：把问题写成可检验判断&quot;">​</a></h1><p>准备一条具体观察和一个想改善的小任务。本页用虚构读书小组练习写清目标、分开事实与解释、比较可区分的假设；随后可读<a href="/life/thinking/reference/case-study">完整讨论案例</a>。</p><h2 id="question" tabindex="-1">问题边界 <a class="header-anchor" href="#question" aria-label="Permalink to &quot;问题边界 {#question}&quot;">​</a></h2><p>思考 问题边界先写对象、目标、期限与约束。虚构读书小组的问题“怎么更有效”太宽；改成“下次30分钟讨论中，让每位参与者至少提出一个有文本依据的问题”，就能观察是否达成。</p><p>题：把“改善学习”改写成可判断的任务。参考：“本周在不看答案时独立解出三道分数题，并记录每题第一处错误。”它只声明本轮任务，不声称解决全部学习问题。若目标是理解而非速度，就不要用刷题数量替代理解证据。</p><h2 id="evidence" tabindex="-1">事实与推断 <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;事实与推断 {#evidence}&quot;">​</a></h2><p>思考 事实与推断必须分开。虚构观察“六人中两人没有发言”是记录；“他们不感兴趣”是解释，可能还有读不懂文本、时间不足或主持分配不均。</p><p>建立三栏：观察、备选解释、区分证据。题：如何区分不感兴趣与没有轮到？答案：查看发言轮次是否实际覆盖所有人，并询问可选择匿名的原因；不能从沉默直接推断动机。只有原话记录时才用引号，不把自己的概括写成别人的陈述。</p><h2 id="alternatives" tabindex="-1">备选解释 <a class="header-anchor" href="#alternatives" aria-label="Permalink to &quot;备选解释 {#alternatives}&quot;">​</a></h2><p>思考 备选解释不是无限列可能，而是保留能被不同证据区分的少量假设。讨论超时可有“材料太多”“规则不清”“没有计时提醒”三种。逐项记录预期：删一半材料仍超时会削弱材料量解释；明确轮次后均衡发言会支持规则解释。</p><p>练习：只做一次缩短材料且新增提醒，能否知道哪个因素有效？答案不能，因为同时改变两项。若现实条件必须一起改，就记录组合干预有效，保留各项因果未分离，而不编造单因素结论。</p>',11)])])}const k=a(s,[["render",r]]);export{f as __pageData,k as default};
